struct Query {
  HRESULT result = S_OK;
  DWORD bytes = 24;
  unsigned calls = 0;
  void* previous = nullptr;
  bool reuse = true;
  DWORD GetDataSize() { return bytes; }
  HRESULT GetData(void* data, DWORD size, DWORD) {
    ++calls;
    if (!size) { require(data == nullptr, "zero-size polling supplied a data pointer"); return result; }
    require(size == bytes, "bad query length reached backend");
    if (previous && previous != data) { reuse = false; }
    previous = data;
    if (result == S_OK) { std::memset(data, 0x5c, size); }
    return result;
  }
};
