static void packetTests() {
  Surface surface;
  surface.desc.Format = D3DFMT_A8R8G8B8; surface.desc.Width = 1; surface.desc.Height = 1;
  RECT rect {0, 0, 1, 1};
  rpcHeader = {1};
  DeviceBridge::blob = {1, 2, 3, 4}; DeviceBridge::blobReads = 0; DeviceBridge::faults = 0;
  extractedHostSurface(&surface, &rect, surface.desc.Format, 4);
  require(!DeviceBridge::faults && surface.locks == 1 && surface.unlocks == 1
    && DeviceBridge::blobReads == 1, "valid x86 four-byte mip rejected by Host ABI");
  require(std::equal(DeviceBridge::blob.begin(), DeviceBridge::blob.end(), surface.bytes.begin())
    && surface.bytes[4] == 0, "small mip widened into padding");
  surface.lockResult = E_FAIL; surface.bytes.fill(0); DeviceBridge::blobReads = 0;
  extractedHostSurface(&surface, &rect, surface.desc.Format, 4);
  require(DeviceBridge::faults == 1 && surface.unlocks == 1 && surface.bytes[0] == 0
    && DeviceBridge::blobReads == 1, "failed surface lock skipped payload or wrote pixels");
  surface.lockResult = S_OK; DeviceBridge::faults = 0; DeviceBridge::blob.resize(3);
  const unsigned oldLocks = surface.locks;
  extractedHostSurface(&surface, &rect, surface.desc.Format, 4);
  require(DeviceBridge::faults == 1 && surface.locks == oldLocks, "short surface packet acquired backend lock");
  DeviceBridge::faults = 0; DeviceBridge::blob = {1, 2, 3, 4};
  surface.desc.Format = D3DFMT_R8G8B8;
  extractedHostSurface(&surface, &rect, surface.desc.Format, 4);
  require(!DeviceBridge::faults && surface.bytes[2] == 3 && surface.bytes[3] == 0, "RGB24 client padding overwrote logical pixels");
  rpcHeader.flags = 1; DeviceBridge::data = {1}; DeviceBridge::position = 0;
  SharedHeap::bytes = {5, 6}; DeviceBridge::faults = 0;
  extractedHostSurface(&surface, &rect, surface.desc.Format, 4);
  require(DeviceBridge::faults == 1, "short shared allocation reached backend");
  rpcHeader.flags = 0;

  D3DVOLUME_DESC desc {}; desc.Width = 4; desc.Height = 3; desc.Depth = 2; desc.Format = D3DFMT_A8R8G8B8;
  D3DBOX box {0, 0, 4, 3, 0, 2};
  std::array<uint8_t, 96> output {};
  DeviceBridge::data = {4, 4, 3, 2}; DeviceBridge::position = 0; DeviceBridge::blob.assign(96, 0x31); DeviceBridge::blobReads = 0;
#ifdef HOST_ROW_PACKETS
  DeviceBridge::rowBytes = 16; DeviceBridge::blobCursor = 0;
  constexpr unsigned expectedReads = 6;
#else
  constexpr unsigned expectedReads = 1;
#endif
  unsigned locks = 0, unlocks = 0;
  auto lock = [&](D3DLOCKED_BOX& value) { ++locks; value = {16, 48, output.data()}; return S_OK; };
  auto unlock = [&]() { ++unlocks; return S_OK; };
#ifdef HOST_FAIL_VOLUME_ALLOCATION
  require(!receiveVolumeUpload(rpcHeader, currentUID, 1, &box, desc, lock, unlock)
    && locks == 0 && unlocks == 0 && DeviceBridge::position == 4 && DeviceBridge::blobReads == 0,
    "row-packet allocation failure escaped or acquired backend lock");
  return;
#endif
  require(receiveVolumeUpload(rpcHeader, currentUID, 1, &box, desc, lock, unlock)
    && locks == 1 && unlocks == 1 && DeviceBridge::position == 4 && DeviceBridge::blobReads == expectedReads,
    "valid volume packet did not consume/copy/unlock exactly once");
  require(std::all_of(output.begin(), output.end(), [](uint8_t value) { return value == 0x31; }), "volume packet changed bytes");
  output.fill(0); DeviceBridge::position = 0; DeviceBridge::blobReads = 0; DeviceBridge::blobCursor = 0;
  require(!receiveVolumeUpload(rpcHeader, currentUID, 1, &box, desc,
    [&](D3DLOCKED_BOX& value) { ++locks; value = {16, 48, output.data()}; return E_FAIL; }, unlock)
    && unlocks == 1 && output[0] == 0 && DeviceBridge::position == 4 && DeviceBridge::blobReads == expectedReads,
    "failed volume lock skipped payload or copied/unlocked");
  DeviceBridge::position = 0; DeviceBridge::data[1] = 0xffffffffu;
  require(!receiveVolumeUpload(rpcHeader, currentUID, 1, &box, desc, lock, unlock) && locks == 2,
    "overflowing volume wire geometry reached backend");
  Buffer buffer;
  DeviceBridge::rowBytes = 0;
  DeviceBridge::faults = 0; rpcHeader.flags = 2; DeviceBridge::blob.assign(16, 0x41); DeviceBridge::unpins = 0;
  extractedHostBuffer(&buffer, 4, 8, 0, nullptr);
  require(!DeviceBridge::faults && buffer.locks == 1 && buffer.unlocks == 1 && DeviceBridge::unpins == 1
    && buffer.bytes[3] == 0 && buffer.bytes[4] == 0x41 && buffer.bytes[11] == 0x41 && buffer.bytes[12] == 0,
    "reserved buffer transfer changed its range or pin lifetime");
  buffer.result = E_FAIL; buffer.bytes.fill(0); DeviceBridge::faults = 0;
  extractedHostBuffer(&buffer, 4, 8, 0, nullptr);
  require(DeviceBridge::faults == 1 && buffer.unlocks == 1 && DeviceBridge::unpins == 2 && buffer.bytes[4] == 0,
    "failed reserved buffer Lock copied, unlocked or leaked pin");
  DeviceBridge::faults = 0; rpcHeader.flags = 1; SharedHeap::bytes.assign(6, 0x32);
  extractedHostBuffer(&buffer, 4, 8, 1, nullptr);
  require(DeviceBridge::faults == 1 && buffer.locks == 2, "short shared buffer allocation reached Lock");
}

static void query(uint32_t id, DWORD bytes, DWORD flags = 0) {
  rpcHeader = {id}; DeviceBridge::data = {bytes, flags}; DeviceBridge::position = 0;
  extractedHostQuery();
  require(DeviceBridge::position == 2, "query did not consume its input packet");
}

static void queryTests() {
  Query backend;
  gpD3DQuery[1] = &backend;
  query(1, backend.bytes);
  require(ServerMessage::result == S_OK && ServerMessage::payload == std::vector<uint8_t>(backend.bytes, 0x5c), "ready query bytes changed");
  for (unsigned i = 0; i < 128; ++i) { query(1, backend.bytes); }
  require(backend.reuse, "query scratch storage was not reused");
  backend.result = S_FALSE;
  query(1, backend.bytes);
  require(ServerMessage::result == S_FALSE && ServerMessage::payload.empty(), "pending query leaked an uninitialized or stale payload");
  backend.result = D3DERR_DEVICELOST;
  query(1, backend.bytes);
  require(ServerMessage::result == D3DERR_DEVICELOST && ServerMessage::payload.empty(), "failed query emitted data");
  const unsigned calls = backend.calls;
  query(1, backend.bytes + 1);
  require(ServerMessage::result == D3DERR_INVALIDCALL && backend.calls == calls, "invalid query size reached backend");
  query(1, backend.bytes, 0x80000000u);
  require(ServerMessage::result == D3DERR_INVALIDCALL && backend.calls == calls, "invalid query flags reached backend");
  query(7, backend.bytes);
  require(ServerMessage::result == D3DERR_INVALIDCALL && gpD3DQuery.size() == 1, "invalid query inserted a null map entry");
  backend.result = S_OK;
  query(1, 0, D3DGETDATA_FLUSH);
  require(ServerMessage::result == S_OK && ServerMessage::payload.empty(), "zero-size query emitted payload");
  for (size_t bytes : {sizeof(BOOL), sizeof(DWORD), sizeof(UINT64), sizeof(D3DDEVINFO_VCACHE),
    sizeof(D3DDEVINFO_RESOURCEMANAGER), sizeof(D3DDEVINFO_D3DVERTEXSTATS), sizeof(D3DDEVINFO_D3D9PIPELINETIMINGS),
    sizeof(D3DDEVINFO_D3D9INTERFACETIMINGS), sizeof(D3DDEVINFO_D3D9STAGETIMINGS),
    sizeof(D3DDEVINFO_D3D9BANDWIDTHTIMINGS), sizeof(D3DDEVINFO_D3D9CACHEUTILIZATION)}) {
    backend.bytes = static_cast<DWORD>(bytes);
    query(1, backend.bytes);
    require(ServerMessage::result == S_OK && ServerMessage::payload.size() == bytes, "legal SDK query result does not fit scratch storage");
  }
}

static void uploadTests() {
  using namespace l4d2_host_upload;
  for (size_t depth : {size_t(1), size_t(2), size_t(7)}) {
    for (size_t rows : {size_t(1), size_t(3), size_t(9)}) {
      for (size_t rowBytes : {size_t(1), size_t(4), size_t(8), size_t(16), size_t(63)}) {
        for (size_t sourcePad : {size_t(0), size_t(5)}) {
          for (size_t destPad : {size_t(0), size_t(7)}) {
            for (size_t slicePad : {size_t(0), size_t(13)}) {
              const size_t sp = rowBytes + sourcePad, dp = rowBytes + destPad;
              const size_t ss = sp * rows + slicePad, ds = dp * rows + slicePad;
              std::vector<uint8_t> source(ss * depth, 0xe1), target(ds * depth + 32, 0xd3), expected(target);
              for (size_t z = 0; z < depth; ++z) {
                for (size_t y = 0; y < rows; ++y) {
                  for (size_t x = 0; x < rowBytes; ++x) {
                    const auto value = static_cast<uint8_t>((x + y * 13 + z * 29) & 255);
                    source[z * ss + y * sp + x] = value;
                    expected[16 + z * ds + y * dp + x] = value;
                  }
                }
              }
              const Layout layout {rowBytes, rows, depth, sp, ss, source.size()};
              require(copy(target.data() + 16, static_cast<int32_t>(dp), static_cast<int32_t>(ds), source.data(), layout), "valid upload rejected");
              require(target == expected, "upload modified padding or produced different pixels");
            }
          }
        }
      }
    }
  }
  std::array<uint8_t, 256> src {}, dst {};
  const Layout layout {8, 4, 1, 8, 0, 32};
  require(!copy(dst.data(), 7, 0, src.data(), layout), "short destination pitch accepted");
  require(!copy(dst.data(), -8, 0, src.data(), layout), "negative destination pitch accepted");
  require(!copy(nullptr, 8, 0, src.data(), layout), "null destination accepted");
  require(!copy(dst.data(), 8, 0, nullptr, layout), "null source accepted");
  Layout shortSource = layout; shortSource.sourceBytes = 31;
  require(!copy(dst.data(), 8, 0, src.data(), shortSource), "short upload payload accepted");
  Layout overlappingSlices {8, 4, 2, 8, 32, 64};
  require(!copy(dst.data(), 8, 31, src.data(), overlappingSlices), "overlapping destination slices accepted");
  Layout huge {8, SIZE_MAX, 1, 8, 0, SIZE_MAX};
  require(!copy(dst.data(), 8, 0, src.data(), huge), "overflowing row layout accepted");
  require(!copy(reinterpret_cast<void*>(UINTPTR_MAX - 8), 8, 0, src.data(), layout), "overflowing destination address accepted");

  unsigned locks = 0, unlocks = 0;
  auto failLock = [&](D3DLOCKED_RECT& locked) {
    ++locks; locked = {8, dst.data()}; return D3DERR_DEVICELOST;
  };
  auto unlock = [&]() { ++unlocks; return S_OK; };
  src.fill(0x66);
  auto failed = surface(src.data(), layout, failLock, unlock);
  require(failed.status() == D3DERR_DEVICELOST && !failed.copied && locks == 1 && unlocks == 0, "failed surface lock copied or unlocked");
  require(dst == std::array<uint8_t, 256>{}, "failed lock wrote destination");
  auto shortLock = [&](D3DLOCKED_RECT& locked) { ++locks; locked = {7, dst.data()}; return S_OK; };
  auto shortResult = surface(src.data(), layout, shortLock, unlock);
  require(shortResult.status() == D3DERR_INVALIDCALL && unlocks == 1, "invalid locked layout was not safely unlocked");
  auto goodLock = [&](D3DLOCKED_RECT& locked) { ++locks; locked = {8, dst.data()}; return S_OK; };
  const unsigned previousLocks = locks;
  auto incomplete = surface(src.data(), shortSource, goodLock, unlock);
  require(incomplete.status() == D3DERR_INVALIDCALL && locks == previousLocks, "incomplete payload acquired backend storage");
  auto unlockFailed = surface(src.data(), layout, goodLock, [&]() { ++unlocks; return E_FAIL; });
  require(unlockFailed.status() == E_FAIL && unlockFailed.copied, "unlock failure was reported as success");
  auto volumeFailed = volume(src.data(), overlappingSlices,
    [&](D3DLOCKED_BOX& locked) { locked = {8, 32, dst.data()}; return E_FAIL; }, unlock);
  require(volumeFailed.status() == E_FAIL && !volumeFailed.copied, "failed volume lock copied data");
  dst.fill(0);
  const unsigned beforeBufferUnlock = unlocks;
  auto bufferFailed = buffer(src.data(), 32,
    [&](void*& target) { target = dst.data(); return E_FAIL; }, unlock);
  require(bufferFailed.status() == E_FAIL && !bufferFailed.copied && dst[0] == 0 && unlocks == beforeBufferUnlock,
    "failed buffer lock copied or unlocked");
  auto bufferNull = buffer(src.data(), 32,
    [&](void*& target) { target = nullptr; return S_OK; }, unlock);
  require(bufferNull.status() == D3DERR_INVALIDCALL && unlocks == beforeBufferUnlock + 1,
    "successful null buffer lock was not safely unlocked");
  auto bufferCopied = buffer(src.data(), 32,
    [&](void*& target) { target = dst.data(); return S_OK; }, unlock);
  require(bufferCopied.status() == S_OK && dst[0] == 0x66 && dst[31] == 0x66 && dst[32] == 0,
    "buffer upload range changed");
}

static void handleTests() {
  int object = 1;
  std::unordered_map<uint32_t, int*> objects {{1, &object}};
  require(l4d2_host_upload::find(objects, 1) == &object, "valid resource lookup failed");
  require(l4d2_host_upload::find(objects, 77) == nullptr && objects.size() == 1, "invalid resource lookup mutated map");
  objects.erase(1);
  require(l4d2_host_upload::find(objects, 1) == nullptr, "destroyed resource lookup returned old object");
}

int main() {
  try {
    uploadTests(); queryTests(); handleTests(); packetTests();
    std::printf("host-upload-contract assertions=%u layouts=360 query=ready/pending/failure/poll handles=valid/invalid/destroy OK\n", assertions);
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "host-upload-contract FAILED: %s\n", error.what()); return 1;
  }
}
